// 1. Leer y parsear el estado completo del usuario desde Redis.
const redisDataString = $input.first().json.estadoUsuarioTexto;
let estadoUsuario = {};
if (redisDataString) {
  try {
    estadoUsuario = JSON.parse(redisDataString);
  } catch (e) {
    estadoUsuario = {};
  }
}
// 2. Leer las variables del nodo "MapeaDatos" directamente
const mapeaDatosOutput = $node["MapeaDatos"].json;
const sessionId = mapeaDatosOutput.sessionId || null;
const apikey = mapeaDatosOutput.apikey || null;
const server_url = mapeaDatosOutput.server_url || null;
const wsp_text = mapeaDatosOutput.wsp_text || null;
// 3. Crear el objeto final, combinando todo
const outputData = {
  // --- Flags generadas ---
  isNewUser: Object.keys(estadoUsuario).length === 0,
  // --- Estado persistente desde Redis ---
  telefono: estadoUsuario.telefono || null,
  nombre: estadoUsuario.nombre || null,
  apellidos: estadoUsuario.apellidos || null,
  email: estadoUsuario.email || null,
  notas: estadoUsuario.notas || '',
  etiqueta_emocional: estadoUsuario.etiqueta_emocional || null,
  etiqueta_asunto: estadoUsuario.etiqueta_asunto || null,
  // --- Variables de contexto del mensaje original ---
  sessionId,
  apikey,
  server_url,
  wsp_text
};
// 4. Retornar la salida
return [{ json: outputData }];

